# The Price of Money: parts 6, 7 and 8.
from story_a import flow, st, WORLD, WASH, NY, LONDON, GENEVA, WBDATA, FLOWS, PARTS
import story_b
UNDEBT = "https://unctad.org/publication/world-of-debt"
UNNEWS = "https://unctad.org/news/global-public-debt-hit-record-102-trillion-2024-striking-developing-countries-hardest"
NYF = "https://www.newyorkfed.org/newsevents/news/research/2026/20261110"
FINDEX = "https://www.worldbank.org/en/news/press-release/2025/07/16/mobile-phone-technology-powers-saving-surge-in-developing-economies"
RPW = "https://remittanceprices.worldbank.org/sites/default/files/rpw_main_report_and_annex_q125_1_0.pdf"
